class Solution {
public:
    int largest1BorderedSquare(vector<vector<int>>& grid) {
        int R = grid.size(), C = grid[0].size();
        vector<vector<int>> right(R, vector<int>(C, 0));
        vector<vector<int>> down(R, vector<int>(C, 0));

        for (int r = R - 1; r >= 0; --r) {
            for (int c = C - 1; c >= 0; --c) {
                if (grid[r][c] == 1) {
                    right[r][c] = 1 + (c + 1 < C ? right[r][c + 1] : 0);
                    down[r][c] = 1 + (r + 1 < R ? down[r + 1][c] : 0);
                }
            }
        }

        int max_d = 0;
        for (int r = 0; r < R; ++r) {
            for (int c = 0; c < C; ++c) {
                int limit = min(right[r][c], down[r][c]);
                for (int d = limit; d > max_d; --d) {
                    if (right[r + d - 1][c] >= d && down[r][c + d - 1] >= d) {
                        max_d = max(max_d, d);
                        break;
                    }
                }
            }
        }
        return max_d * max_d;
    }
};

class Solution {
    public int largest1BorderedSquare(int[][] grid) {
        int R = grid.length, C = grid[0].length;
        int[][] right = new int[R][C];
        int[][] down = new int[R][C];

        for (int r = R - 1; r >= 0; r--) {
            for (int c = C - 1; c >= 0; c--) {
                if (grid[r][c] == 1) {
                    right[r][c] = 1 + (c + 1 < C ? right[r][c + 1] : 0);
                    down[r][c] = 1 + (r + 1 < R ? down[r + 1][c] : 0);
                }
            }
        }

        int maxD = 0;
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                int limit = Math.min(right[r][c], down[r][c]);
                for (int d = limit; d > maxD; d--) {
                    if (right[r + d - 1][c] >= d && down[r][c + d - 1] >= d) {
                        maxD = Math.max(maxD, d);
                        break;
                    }
                }
            }
        }
        return maxD * maxD;
    }
}

var largest1BorderedSquare = function(grid) {
    const R = grid.length, C = grid[0].length;
    const right = Array.from({ length: R }, () => new Array(C).fill(0));
    const down = Array.from({ length: R }, () => new Array(C).fill(0));

    for (let r = R - 1; r >= 0; r--) {
        for (let c = C - 1; c >= 0; c--) {
            if (grid[r][c] === 1) {
                right[r][c] = 1 + (c + 1 < C ? right[r][c + 1] : 0);
                down[r][c] = 1 + (r + 1 < R ? down[r + 1][c] : 0);
            }
        }
    }

    let maxD = 0;
    for (let r = 0; r < R; r++) {
        for (let c = 0; c < C; c++) {
            const limit = Math.min(right[r][c], down[r][c]);
            for (let d = limit; d > maxD; d--) {
                if (right[r + d - 1][c] >= d && down[r][c + d - 1] >= d) {
                    maxD = Math.max(maxD, d);
                    break;
                }
            }
        }
    }
    return maxD * maxD;
};
